const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
const clone=value=>structuredClone(value);
const id=(prefix="id")=>`${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const total=object=>Object.values(object||{}).reduce((sum,value)=>sum+Math.max(0,Number(value)||0),0);
const money=value=>`$${Number(value||0).toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:2})}`;
const mergeDefaults=(base,input)=>{
  if(Array.isArray(base)) return Array.isArray(input)?input:clone(base);
  if(base&&typeof base==="object"){
    const source=input&&typeof input==="object"&&!Array.isArray(input)?input:{};
    return Object.fromEntries(Object.entries(base).map(([key,value])=>[key,mergeDefaults(value,source[key])]).concat(Object.entries(source).filter(([key])=>!(key in base))));
  }
  return input===undefined||input===null?base:input;
};

export const levelForXp=xp=>clamp(1+Math.floor(Math.sqrt(Math.max(0,xp)/100)),1,18);
export const xpForLevel=level=>Math.pow(Math.max(0,level-1),2)*100;
export const levelTitle=level=>[...LEVEL_TITLES].reverse().find(([required])=>level>=required)?.[1]||"Stand Starter";

