  teleportOutside(regionId){const region=OUTSIDE_REGION_BY_ID[regionId],progress=this.state.outside.regions[regionId];if(!region||!progress)return this.result(false,"Region not found.");if(!progress.unlocked||this.outsideRegionCompletion(regionId)<60)return this.result(false,`Develop ${region.name} to 60% to activate regional fast travel.`);this.state.player={x:region.x,y:region.y,district:this.state.player.district};this.state.outside.currentRegion=regionId;progress.visits++;return this.result(true,`Traveled to ${region.name} — elevation ${region.elevation.toLocaleString()}m.`);}
  performOutsideRegionInteraction(regionId){const region=OUTSIDE_REGION_BY_ID[regionId],progress=this.state.outside.regions[regionId];if(!region||!progress)return this.result(false,"Region not found.");if(!progress.discovered)return this.result(false,`Discover ${region.name} before using its landmark.`);const cooldown=60000,remainingMs=cooldown-(this.now-(progress.lastSpecialAt||0));if(progress.lastSpecialAt&&remainingMs>0)return this.result(false,`${Math.ceil(remainingMs/1000)} seconds until ${region.name}'s special interaction is ready again.`);progress.lastSpecialAt=this.now;progress.specialCount=(progress.specialCount||0)+1;progress.questCompleted=true;const fruit=(region.fruits||[]).map(name=>FRUITS.find(item=>item.name===name||item.id===name)).find(Boolean);if(fruit&&this.canStoreFruit(1))this.state.fruitInventory[fruit.id]=(this.state.fruitInventory[fruit.id]||0)+1;else this.state.outside.materials.timber=(this.state.outside.materials.timber||0)+1;const cash=8+Math.max(1,region.index),xp=5+Math.ceil(region.index/2);this.earnCash(cash,`${region.name} activity`);this.addXp(xp);return this.result(true,`${region.specialInteraction||`You explored ${region.name}.`} Regional quest progress saved; +$${cash}, +${xp} XP${fruit?`, and 1 ${fruit.name}`:", and 1 Timber"}.`);}
