  buyOfficeUpgrade(upgradeId){const upgrade=OFFICE_UPGRADES.find(item=>item.id===upgradeId);if(!upgrade)return this.result(false,"Office upgrade not found.");if(this.state.office.upgrades.includes(upgradeId))return this.result(false,"This office upgrade is already installed.");if(this.state.level<upgrade.level)return this.result(false,`Reach Empire level ${upgrade.level}.`);const branch=OFFICE_UPGRADES.filter(item=>item.category===upgrade.category),position=branch.findIndex(item=>item.id===upgradeId),previous=position>0?branch[position-1]:null;if(previous&&!this.state.office.upgrades.includes(previous.id))return this.result(false,`Install ${previous.name} first.`);const paid=this.spend({cash:upgrade.cashCost,coins:upgrade.coinCost});if(!paid.ok)return paid;this.state.office.upgrades.push(upgradeId);this.state.office.level=clamp(1+Math.floor(this.state.office.upgrades.length/10),1,5);if(upgradeId==="company-safe")this.state.office.safe+=100;this.updatePhone();return this.result(true,`${upgrade.name} installed in the office.`);}
  respondMessage(messageId,response){const message=this.state.phone.messages.find(item=>item.id===messageId);if(!message)return this.result(false,"Message not found.");if(message.response)return this.result(false,"You already responded to this message.");if(!message.responses?.includes(response))return this.result(false,"Choose one of the available responses.");message.response=response;message.unread=false;this.state.reputation=clamp(this.state.reputation+1,0,100);return this.result(true,`Replied: ${response}`);}
  negotiateOrder(orderId,choice){const order=this.state.phone.orders.find(item=>item.id===orderId);if(!order)return this.result(false,"Order not found.");if(order.status!=="offered")return this.result(false,"This order was already negotiated.");if(order.deadline<=this.now){order.status="expired";return this.result(false,"This customer offer expired before negotiation.");}const multipliers={accept:1,"more-10":1.1,"more-25":1.25,premium:1.3,faster:1.2,"more-time":.92,custom:1.15,decline:0};if(!(choice in multipliers))return this.result(false,"Unknown negotiation choice.");if(choice==="custom"&&!this.state.office.upgrades.includes("custom-counteroffers"))return this.result(false,"Install Custom Counteroffers in the Office first.");order.negotiationHistory=Array.isArray(order.negotiationHistory)?order.negotiationHistory:[];order.negotiationHistory.push({choice,at:this.now,offeredPayment:order.payment});if(choice==="decline"){order.status="declined";return this.result(true,"Order declined politely.");}const acceptance=choice==="more-25"?.55:choice==="premium"?.72:choice==="custom"?.75:.9;if(this.random()>acceptance){order.status="declined";return this.result(true,"The customer declined the counteroffer.");}order.status="accepted";order.payment=Math.round(order.payment*multipliers[choice]);if(choice==="more-time")order.deadline+=120000;order.negotiation=choice;return this.result(true,`Order accepted at $${order.payment}.`);}
  supplyOrder(orderId){const order=this.state.phone.orders.find(item=>item.id===orderId);if(!order||order.status!=="accepted")return this.result(false,"Accept this order before supplying it.");if(order.deadline<=this.now){order.status="expired";return this.result(false,"This accepted order expired before it was supplied.");}if(this.state.reputation<order.reputationRequirement)return this.result(false,`Need ${Math.ceil(order.reputationRequirement-this.state.reputation)} more company reputation.`);if(order.kind==="fruit"&&(this.state.fruitQuality[order.item]||0)<order.quality)return this.result(false,`Need ${QUALITY_NAMES[order.quality]} quality ${FRUIT_BY_ID[order.item]?.name}.`);const inventory=order.kind==="fruit"?this.state.fruitInventory:this.state.productInventory;if((inventory[order.item]||0)<order.quantity)return this.result(false,`Need ${order.quantity-(inventory[order.item]||0)} more items.`);inventory[order.item]-=order.quantity;order.status="supplied";const payment={id:id("payment"),orderId,amount:order.payment,collected:false,from:order.customer};this.state.phone.payments.push(payment);this.state.phone.messages.unshift({id:id("message"),from:"Fruitopia Pay",subject:"Customer payment ready",body:`${order.customer} sent $${order.payment} for order ${order.id}.`,unread:true,paymentId:payment.id,orderId:order.id,responses:[]});this.state.stats.orders++;return this.result(true,"Order supplied. Payment is waiting in Messages.");}
