  invest(fundId,amount){amount=Math.max(1,Math.floor(amount));const fund=["orchard-equipment-fund","market-expansion-fund","fruit-research-fund"].includes(fundId)?fundId:null;if(!fund)return this.result(false,"Fictional fund not found.");const paid=this.spend({cash:amount});if(!paid.ok)return paid;const rates={"orchard-equipment-fund":.05,"market-expansion-fund":.08,"fruit-research-fund":.12};this.state.phone.investments.push({id:id("investment"),fundId,principal:amount,readyAt:this.now+60000,collected:false,returnAmount:Math.round(amount*(1+rates[fundId]))});return this.result(true,`Invested $${amount} in this fictional in-game fund.`);}
