  startEvent(eventId=null){const event=eventId?EVENTS.find(item=>item.id===eventId):EVENTS[Math.floor(this.random()*EVENTS.length)];if(!event)return this.result(false,"Event not found.");this.state.event={active:event.id,endsAt:this.now+event.duration*1000,history:[...(this.state.event.history||[]),event.id]};if(event.effect==="harvest")for(const tree of this.state.trees){if(tree.status!=="diseased"){tree.status=event.name==="Fruit Coin Shower"?"golden":"ripe";tree.golden=event.name==="Fruit Coin Shower";tree.readyAt=0;}}if(event.effect==="growth")for(const tree of this.state.trees)if(tree.readyAt>this.now)tree.readyAt=this.now+(tree.readyAt-this.now)*.5;if(event.effect==="delivery")for(const delivery of this.state.activeDeliveries)if(!delivery.paid)delivery.readyAt+=event.name==="Delivery Traffic"?30000:-Math.min(15000,delivery.readyAt-this.now);if(event.effect==="research")this.state.researchPoints+=3;if(event.effect==="sale")this.state.featured.endsAt=Math.max(this.state.featured.endsAt,this.now+event.duration*1000);const mountain=MOUNTAIN_WEATHER.find(item=>item.name===event.name);if(mountain&&!this.state.outside.weather.active)this.state.outside.weather={active:mountain.id,endsAt:this.state.event.endsAt,history:[...(this.state.outside.weather.history||[]),mountain.id]};const message={id:id("event-message"),from:"Fruitopia Events",subject:event.name,body:`${event.name} is changing company conditions for ${event.duration} seconds.`,unread:true,responses:["Share with the team","Adjust operations"]};this.state.phone.messages.unshift(message);this.pushPhoneNotification("event",`event:${event.id}:${this.state.event.endsAt}`,event.name,message.body,"events");return this.result(true,`${event.icon} ${event.name} has begun and changed the ${event.effect} economy.`);}
  generateWorkerVisit(){const employee=Object.values(this.state.workers)[Math.floor(this.random()*Object.keys(this.state.workers).length)];if(!employee)return null;const types=["raise","promotion","equipment","idea","time-off","stress","transfer","training","thanks","inventory","discovery","emergency"],type=types[Math.floor(this.random()*types.length)],request={id:id("visit"),workerId:employee.workerId,type,status:"waiting",createdAt:this.now};this.state.workerRequests.push(request);this.state.office.visitors.push(employee.workerId);const worker=WORKER_BY_ID[employee.workerId];this.state.phone.messages.unshift({id:id("worker-message"),from:worker.name,subject:`Office visit: ${type.replace("-"," ")}`,body:`Could we talk in the office about ${type.replace("-"," ")}?`,unread:true,responses:["Come in","I will follow up"]});return request;}
  respondWorkerVisit(requestId,choice){const request=this.state.workerRequests.find(item=>item.id===requestId),employee=this.state.workers[request?.workerId],worker=WORKER_BY_ID[request?.workerId];if(!request||!employee||!worker)return this.result(false,"Worker visit not found.");if(request.status!=="waiting")return this.result(false,"This office visit was already resolved.");let cost=0;if(["support","approve"].includes(choice)&&["raise","equipment","training","emergency"].includes(request.type))cost=20+employee.skill*10;if(cost){const paid=this.spend({cash:cost});if(!paid.ok)return paid;}request.status="resolved";request.choice=choice;this.state.office.visitors=this.state.office.visitors.filter(id=>id!==request.workerId);if(["support","approve"].includes(choice)){employee.happiness=clamp(employee.happiness+10,0,100);employee.loyalty=clamp(employee.loyalty+8,0,100);employee.skill+=request.type==="training"?1:0;}else{employee.happiness=clamp(employee.happiness-6,0,100);employee.loyalty=clamp(employee.loyalty-5,0,100);}employee.memories.push(`${choice==="support"||choice==="approve"?"Received support":"Was asked to wait"} during an office visit about ${request.type.replace("-"," ")}.`);return this.result(true,`${worker.name}'s ${request.type.replace("-"," ")} conversation was resolved.`);}
  investigateSecret(secretId,mode="clue"){const secret=SECRETS.find(item=>item.id===secretId),progress=this.state.secrets[secretId];if(!secret||!progress)return this.result(false,"Secret not found.");if(progress.discovered)return this.result(false,"This secret is already discovered.");if(mode==="clue"){const paid=this.spend({research:secret.researchCost});if(!paid.ok)return paid;progress.clues=clamp(progress.clues+1,0,3);return this.result(true,`${secret.clue} (${progress.clues}/3 clues)`);}if(progress.clues<2)return this.result(false,"Find at least two clues before investigating.");const paid=this.spend({cash:secret.cashCost});if(!paid.ok)return paid;progress.investigated=true;progress.discovered=true;this.earnCoins(3+SECRETS.indexOf(secret),"Secret discovered");this.addXp(60+SECRETS.indexOf(secret)*10);return this.result(true,`${secret.name} discovered! ${secret.unlock}`);}
  checkQuestProgress(){for(const quest of this.state.quests)quest.progress=Math.min(quest.target,this.state.stats[quest.stat]||0);}
  claimQuest(questId){const quest=this.state.quests.find(item=>item.id===questId);if(!quest)return this.result(false,"Quest not found.");this.checkQuestProgress();if((quest.progress||0)<quest.target)return this.result(false,`${quest.target-(quest.progress||0)} more required.`);if(quest.claimed)return this.result(false,"Quest reward already claimed.");quest.claimed=true;if(quest.reward.cash)this.earnCash(quest.reward.cash,"Daily quest");if(quest.reward.coins)this.earnCoins(quest.reward.coins,"Daily quest");this.addXp(quest.reward.xp||0);return this.result(true,`${quest.name} reward claimed.`);}
