  updateAchievements(){for(const achievement of ACHIEVEMENTS){if(this.state.achievements[achievement.id])continue;if((this.state.stats[achievement.stat]||0)>=achievement.target){this.state.achievements[achievement.id]={earnedAt:this.now,reward:achievement.reward};this.earnCoins(achievement.reward,`${achievement.name} achievement`);}}}
  canBeginSeason(){return this.state.level>=18||this.state.lifetimeCash>=250000;}
  beginSeason(){if(!this.canBeginSeason())return this.result(false,"Reach level 18 or $250,000 lifetime Cash first.");const old=this.state,seeds=Math.max(1,Math.floor(old.level/3)+Math.floor(old.lifetimeCash/250000));const fresh=createDefaultState(this.now);fresh.goldenSeeds=old.goldenSeeds+seeds;fresh.season=old.season+1;fresh.evolutionAge=clamp(old.evolutionAge+1,0,EVOLUTION_AGES.length-1);fresh.settings=clone(old.settings);fresh.phone.theme=old.phone.theme;fresh.upgradeCenter.pinned=clone(old.upgradeCenter.pinned);fresh.achievements=clone(old.achievements);fresh.minigames.highScores=clone(old.minigames.highScores);fresh.discoveredFruit=clone(old.discoveredFruit);fresh.researchNotebook=clone(old.researchNotebook);fresh.patents=clone(old.patents);fresh.permanent=clone(old.permanent);fresh.office.decorations=clone(old.office.decorations);fresh.sewer=clone(old.sewer);fresh.sewer.active=false;for(const [workerId,employee] of Object.entries(old.workers)){if(fresh.workers[workerId]){fresh.workers[workerId].loyalty=employee.loyalty;fresh.workers[workerId].memories=clone(employee.memories);}}this.state=fresh;return this.result(true,`Season ${fresh.season} began with ${seeds} new Golden Seeds in the ${EVOLUTION_AGES[fresh.evolutionAge]}.`,{seeds});}
  buyPermanent(upgradeId){const upgrade=GOLDEN_SEED_UPGRADES.find(item=>item.id===upgradeId);if(!upgrade)return this.result(false,"Permanent upgrade not found.");const current=this.state.permanent[upgradeId]||0,cost=current+1;if(this.state.goldenSeeds<cost)return this.result(false,`Need ${cost-this.state.goldenSeeds} more Golden Seeds.`);this.state.goldenSeeds-=cost;this.state.permanent[upgradeId]=current+1;this.recalculate();return this.result(true,`${upgrade.name} is now level ${current+1}.`);}
  completeSewerQuest(questId){const progress=this.state.sewer.quests[questId];if(progress&&!progress.completed){progress.completed=true;progress.completedAt=this.now;this.notify("Sewer quest complete",SEWER_QUESTS.find(quest=>quest.id===questId)?.name||questId,"success");}return progress;}
