  investigateSewerSecret(secretId,mode="clue"){const secret=SEWER_SECRETS.find(item=>item.id===secretId),progress=this.state.sewer.secrets[secretId];if(!secret||!progress)return this.result(false,"Sewer secret not found.");if(progress.discovered)return this.result(false,"This sewer secret is already discovered.");if(mode==="clue"){const paid=this.spend({research:2});if(!paid.ok)return paid;this.addSewerSecretClue(secretId);return this.result(true,`A new underground clue points toward ${secret.name}. (${progress.clues}/${secret.clueTarget})`);}if(progress.clues<secret.clueTarget)return this.result(false,`Find ${secret.clueTarget-progress.clues} more clue${secret.clueTarget-progress.clues===1?"":"s"}.`);const paid=this.spend({cash:50});if(!paid.ok)return paid;progress.discovered=true;progress.discoveredAt=this.now;this.earnCoins(2,"Sewer secret discovered");this.addXp(35);return this.result(true,`${secret.name} discovered beneath Fruitopia!`);}
  claimSewerQuest(questId){const quest=SEWER_QUESTS.find(item=>item.id===questId),progress=this.state.sewer.quests[questId];if(!quest||!progress)return this.result(false,"Sewer quest not found.");if(!progress.completed)return this.result(false,"Complete this sewer quest first.");if(progress.claimed)return this.result(false,"This sewer quest reward was already claimed.");progress.claimed=true;const reward=quest.reward;if(reward.cash)this.earnCash(reward.cash,"Sewer quest");if(reward.coins)this.earnCoins(reward.coins,"Sewer quest");if(reward.xp)this.addXp(reward.xp);if(reward.research)this.state.researchPoints+=reward.research;if(reward.chips)this.addClubChips(reward.chips);if(reward.item)this.state.sewer.inventory[reward.item]=(this.state.sewer.inventory[reward.item]||0)+1;return this.result(true,`${quest.name} reward claimed.`);}
  inspectManhole(entranceId,action="inspect"){const entrance=SEWER_ENTRANCE_BY_ID[entranceId],progress=this.state.sewer.entrances[entranceId];if(!entrance||!progress)return this.result(false,"Manhole not found.");progress.discovered=true;progress.status=progress.open?"opened":"locked";if(action==="inspect"){progress.symbolRead=true;if(entranceId==="sunny-manhole")this.state.sewer.unlocked=true;this.addSewerSecretClue("the-green-water-formula");return this.result(true,"A carved apple surrounds three wavy lines. Warm road noise fades into a green-lit tunnel below.");}if(action==="listen"){progress.listened=true;return this.result(true,"Drip… glub… machinery turns far below, followed by three cheerful pipe knocks.");}if(action==="symbol"){progress.symbolRead=true;return this.result(true,entranceId==="mafia-alley-manhole"?"A tiny golden grape marks an exit that only opens from the club.":"Six painted peels form an old maintenance seal.");}if(action==="open"){if(progress.open)return this.result(true,"The cover is already open. The accessible ladder is ready.");let allowed=entranceId==="sunny-manhole"&&progress.symbolRead;if(entranceId==="depot-manhole")allowed=this.state.sewer.pumps.states["red-pump"];if(entranceId==="market-manhole")allowed=progress.openedFromUnderground;if(entranceId==="juice-manhole")allowed=this.state.sewer.lab.restored;if(entranceId==="mafia-alley-manhole")allowed=this.state.sewer.mafia.membership;if(!allowed)return this.result(false,entrance.unlock);progress.open=true;progress.locked=false;progress.permanent=true;progress.status="permanently-unlocked";this.state.sewer.unlocked=true;if(total(Object.fromEntries(SEWER_CONTAINERS.map(container=>[container.id,this.state.sewer.inventory[container.id]||0])))<1)this.state.sewer.inventory["empty-bottle"]++;this.completeSewerQuest("open-the-first-manhole");return this.result(true,`${entrance.name} opens permanently with a clunk. A ladder and green light appear below.`);}return this.result(false,"Choose inspect, listen, read the symbol, or open.");}
