  enterSewer(entranceId){const entrance=SEWER_ENTRANCE_BY_ID[entranceId],progress=this.state.sewer.entrances[entranceId];if(!entrance||!progress?.open)return this.result(false,"Open this manhole before entering.");this.state.sewer.active=true;this.state.sewer.lastEntrance=entranceId;this.state.sewer.surfacePosition=clone(this.state.player);this.state.sewer.player={x:entrance.sewerX,y:entrance.sewerY,section:entrance.zone};this.state.sewer.maze.crossedStartLine=false;this.state.sewer.maze.markers=[];this.discoverSewerSection(entrance.zone);return this.result(true,`You climb into ${SEWER_SECTIONS.find(section=>section.id===entrance.zone)?.name||"the sewer"}. The surface ladder remains accessible.`);}
