  discoverSewerSection(section){const sewer=this.state.sewer;if(!section)return;sewer.discovery.rooms[section]=true;const discovered=Object.keys(sewer.discovery.rooms).filter(id=>SEWER_SECTIONS.some(zone=>zone.id===id)).length;sewer.discovery.sewerPercent=Math.round(discovered/SEWER_SECTIONS.length*100);const mazeZones=SEWER_SECTIONS.filter(zone=>zone.maze);const mazeSeen=mazeZones.filter(zone=>sewer.discovery.rooms[zone.id]).length;sewer.discovery.mazePercent=Math.round(mazeSeen/mazeZones.length*100);}
  updateSewerLocation(player=this.state.sewer.player){if(!this.state.sewer.active)return;let section=SEWER_SECTIONS.filter(zone=>player.x>=zone.x-zone.w/2&&player.x<=zone.x+zone.w/2&&player.y>=zone.y-zone.h/2&&player.y<=zone.y+zone.h/2).sort((a,b)=>(a.w*a.h)-(b.w*b.h))[0]?.id||player.section||"front-drain-entrance";player.section=section;this.discoverSewerSection(section);const maze=this.state.sewer.maze,mazeMap=SEWER_LAYOUT_POINTS.mazeMap;maze.atEntrance=Math.hypot(player.x-mazeMap.x,player.y-mazeMap.y)<=8&&!maze.crossedStartLine;if(maze.atEntrance)this.completeSewerQuest("find-the-maze-entrance");if(player.y>=SEWER_LAYOUT_POINTS.mazeStart.y&&["red-pipe-quarter","blue-canal-quarter","yellow-maintenance-quarter","green-root-quarter","black-pipe-center"].includes(section))maze.crossedStartLine=true;if(section==="sewer-test-laboratory"){this.state.sewer.lab.discovered=true;this.completeSewerQuest("discover-the-sewer-test-lab");}if(section==="forgotten-fruit-laboratory")this.discoverForgottenLab();if(["mafia-entrance","fruit-mafia-club","underground-machine-room"].includes(section))this.state.sewer.discovery.club=true;if(section==="black-pipe-center"&&maze.centerOpen)maze.centerReached=true;return section;}
